insert into public.tipos_aparelho (id, item, nome, para_que, neutro, central, alimentacao, cuidados, passos) values
  ('INT_TOUCH', 'luz', 'Interruptor inteligente (1 a 4 teclas)', 'Troca o interruptor comum. Liga pelo toque, pelo celular e por voz.', 'Sim (maioria)', 'Só se for Zigbee', 'Rede elétrica', 'Confirmar neutro na caixa 4x2. Respeitar a corrente máxima por tecla.', '1. Desligue o disjuntor do circuito. 2. Confira se há fase, neutro e retorno na caixa. 3. Fase em L, neutro em N, cada retorno em L1, L2... 4. Fixe na caixa e religue o disjuntor. 5. Pareie no app do fabricante e vincule à Alexa/Google.'),
  ('MOD_RELE', 'luz', 'Módulo relé (atrás do interruptor)', 'Mantém o interruptor e o espelho do cliente. O módulo fica escondido na caixa.', 'Sim (maioria)', 'Só se for Zigbee', 'Rede elétrica', 'Precisa de espaço na caixa (caixa funda).', '1. Desligue o disjuntor do circuito. 2. Ligue fase e neutro no módulo. 3. Ligue o interruptor existente na entrada S1/S2. 4. Ligue a lâmpada na saída do módulo. 5. Acomode na caixa, religue e pareie.'),
  ('DIMMER', 'luz', 'Dimmer inteligente', 'Controla a intensidade da luz.', 'Verificar', 'Só se for Zigbee', 'Rede elétrica', 'Só para lâmpadas dimerizáveis. Respeitar potência máxima.', '1. Desligue o disjuntor do circuito. 2. Confira se as lâmpadas são dimerizáveis. 3. Ligue conforme o manual. 4. Religue e pareie.'),
  ('LAMPADA', 'luz', 'Lâmpada inteligente', 'Troca só a lâmpada (soquete E27). Muda cor e intensidade.', 'Não', 'Não', 'Rede elétrica', 'O interruptor da parede precisa ficar sempre ligado.', '1. Troque a lâmpada. 2. Deixe o interruptor ligado. 3. Pareie no app.'),
  ('TOMADA_EMBUTIR', 'tomada', 'Tomada inteligente de embutir', 'Substitui a tomada da parede. Liga, desliga e mede consumo.', 'Sim', 'Só se for Zigbee', 'Rede elétrica', 'Conferir 127 V ou 220 V. Aparelho acima de 10 A: tomada 20 A e circuito exclusivo.', '1. Desligue o disjuntor do circuito. 2. Confira a tensão (127 V ou 220 V): o produto precisa aceitar. 3. Fase em L, neutro em N, terra no borne de terra. 4. Fixe, religue e pareie.'),
  ('PLUGUE', 'tomada', 'Plugue inteligente (adaptador)', 'Encaixa na tomada existente, sem obra.', 'Não', 'Não', 'Tomada', 'Respeitar a corrente máxima do adaptador.', '1. Encaixe na tomada. 2. Ligue o aparelho no plugue. 3. Pareie no app.'),
  ('CORTINA_MOTOR', 'cortina', 'Motor de cortina com trilho', 'Abre e fecha a cortina pelo celular e por voz.', 'Verificar', 'Verificar', 'Tomada ou ponto de energia', 'Precisa de ponto de energia perto do trilho.', '1. Meça a janela e confirme o tamanho do trilho. 2. Instale o trilho. 3. Leve energia até o motor. 4. Encaixe o motor e ajuste os fins de curso. 5. Pareie.'),
  ('CORTINA_CONTROLADOR', 'cortina', 'Controlador de cortina (para motor existente)', 'Deixa inteligente um motor de cortina ou persiana que já existe.', 'Verificar', 'Não', 'Rede elétrica', 'Conferir compatibilidade com o motor existente.', '1. Desligue o disjuntor do circuito. 2. Ligue o controlador entre a alimentação e o motor, conforme o manual. 3. Religue, pareie e ajuste o tempo de abertura.'),
  ('IR_UNIVERSAL', 'ar_condicionado, tv', 'Controle universal infravermelho', 'Comanda o ar e a TV que já existem, imitando o controle remoto.', 'Não', 'Não', 'Fonte USB', 'Precisa "enxergar" o aparelho. 1 por cômodo atende ar e TV juntos.', '1. Posicione de frente para o ar e a TV. 2. Ligue na fonte USB. 3. Pareie no app. 4. Cadastre o ar e a TV escolhendo a marca. 5. Teste ligar, desligar e mudar a temperatura.'),
  ('PORTAO_MODULO', 'portao', 'Módulo/central Wi-Fi para motor existente', 'Faz o motor de portão que já existe abrir pelo celular.', '—', 'Não', 'Central do motor', 'Conferir compatibilidade com a central do motor.', '1. Desligue a energia do motor. 2. Ligue o módulo na central, conforme o manual. 3. Religue e pareie. 4. Teste abrir, fechar e o sensor antiesmagamento.'),
  ('PORTAO_MOTOR', 'portao', 'Motor de portão com Wi-Fi (novo)', 'Motor novo que já vem com Wi-Fi.', '—', 'Não', 'Rede elétrica', 'Circuito exclusivo com disjuntor. Conferir tensão do motor (127/220 V) e peso do portão.', '1. Confira peso e tipo do portão (deslizante/basculante). 2. Passe circuito exclusivo com disjuntor. 3. Instale motor e cremalheira. 4. Ajuste fins de curso. 5. Pareie e teste.'),
  ('FECHADURA', 'fechadura', 'Fechadura digital Wi-Fi', 'Abre por senha, digital, cartão ou celular.', 'Não', 'Só se for Zigbee', 'Pilhas', 'Conferir espessura da porta e tipo da fechadura existente. Manter a chave de emergência.', '1. Meça a porta. 2. Retire a fechadura antiga. 3. Fure conforme o gabarito. 4. Instale as partes externa e interna. 5. Coloque as pilhas, cadastre senhas e pareie.'),
  ('CAMERA_INTERNA', 'camera', 'Câmera interna Wi-Fi', 'Vigia ambientes internos. Grava em cartão ou na nuvem.', '—', 'Não', 'Fonte (tomada)', 'Tomada próxima e sinal Wi-Fi no local.', '1. Escolha o ponto com visão do ambiente. 2. Ligue a fonte. 3. Fixe e direcione. 4. Pareie e insira o cartão de memória.'),
  ('CAMERA_EXTERNA_IA', 'camera', 'Câmera externa com detecção de pessoas', 'Avisa no celular quando passa uma pessoa, não só qualquer movimento.', '—', 'Não', 'Fonte (protegida)', 'Proteção IP66/IP67. Energia protegida. LGPD: placa "ambiente monitorado" e não filmar a área do vizinho.', '1. Escolha o ponto (cerca de 2,5 m, sem contraluz). 2. Leve energia com fonte protegida. 3. Fixe e direcione. 4. Pareie e ative a detecção de pessoas. 5. Insira o cartão de memória.'),
  ('SENSOR_PRESENCA', 'sensor', 'Sensor de presença', 'Acende a luz ou avisa quando alguém passa.', 'Não', 'Verificar', 'Pilha', 'Altura e ângulo conforme o manual.', '1. Pareie no app. 2. Fixe no canto, a cerca de 2,2 m. 3. Crie a automação (ex.: acender a luz).'),
  ('SENSOR_ABERTURA', 'sensor', 'Sensor de abertura (porta/janela)', 'Avisa quando a porta ou a janela abre.', 'Não', 'Verificar', 'Pilha', 'Alinhar as duas peças (sensor e ímã).', '1. Pareie no app. 2. Cole o sensor no batente e o ímã na porta, alinhados. 3. Teste abrindo e fechando.'),
  ('SENSOR_VAZAMENTO', 'sensor', 'Sensor de vazamento de água', 'Avisa vazamento embaixo da pia ou da máquina.', 'Não', 'Verificar', 'Pilha', 'Instalar no chão, no ponto mais baixo.', '1. Pareie no app. 2. Coloque no chão perto da pia ou da máquina. 3. Teste com um pouco de água.'),
  ('SENSOR_GAS', 'sensor', 'Sensor de gás', 'Avisa vazamento de gás de cozinha.', '—', 'Verificar', 'Tomada', 'Gás de botijão (GLP): perto do chão. Gás encanado (natural): perto do teto.', '1. Confira o tipo de gás. 2. Instale na altura certa, perto do fogão, mas não em cima dele. 3. Ligue na tomada e pareie.'),
  ('SENSOR_FUMACA', 'sensor', 'Sensor de fumaça', 'Avisa fumaça.', 'Não', 'Verificar', 'Pilha', 'No teto, longe do fogão para evitar alarme falso.', '1. Pareie no app. 2. Fixe no teto do corredor ou do quarto. 3. Teste pelo botão do sensor.'),
  ('CENTRAL_ZIGBEE', '(infraestrutura)', 'Central Zigbee (gateway)', 'Necessária quando o projeto usa aparelhos Zigbee.', '—', '—', 'Tomada/USB', 'Perto do roteador. Uma por projeto, da mesma família dos aparelhos.', '1. Ligue perto do roteador. 2. Pareie no app. 3. Adicione os aparelhos Zigbee a partir dela.')
