insert into public.regras_eletricas (id, quando, acao, mensagem, servico, servico_id, base) values
  ('R01', 'Tensão da casa escolhida (127 V ou 220 V)', 'Mostra só aparelhos que aceitam essa tensão (bivolt passa sempre).', 'Mostrando aparelhos para 220 V.', '—', null, 'Manual do fabricante'),
  ('R02', 'Tem Luz e a casa NÃO tem neutro na caixa', 'Prefere modelos sem neutro; se não houver, adiciona o serviço.', 'Estes interruptores precisam de neutro. A casa não tem neutro na caixa.', 'Passar neutro até a caixa (por ponto)', 'S14', 'Manual do fabricante'),
  ('R03', 'Tem Luz e neutro = Não sei', 'Mostra alerta antes da lista.', 'Confira o neutro na caixa antes de comprar.', '—', null, '—'),
  ('R04', 'Tomada vai ligar aparelho forte (acima de 10 A)', 'Troca por tomada 20 A e adiciona circuito exclusivo.', 'Aparelho acima de 10 A precisa de circuito exclusivo.', 'Circuito exclusivo com disjuntor', 'S15', 'NBR 5410'),
  ('R05', 'Ar-condicionado novo (vai instalar)', 'Adiciona circuito exclusivo com disjuntor para cada aparelho.', 'Cada ar novo precisa de circuito e disjuntor próprios (ver manual do aparelho).', 'Circuito exclusivo + disjuntor (por aparelho)', 'S15', 'NBR 5410 + manual'),
  ('R06', 'Ar-condicionado já instalado', 'Só controle infravermelho, sem obra elétrica.', '—', '—', null, '—'),
  ('R07', 'Portão com motor novo', 'Adiciona circuito exclusivo; filtra motor pela tensão da casa.', 'Motor de portão: circuito exclusivo e tensão igual à da casa.', 'Circuito exclusivo para o motor', 'S15', 'Manual do fabricante'),
  ('R08', 'Circuito novo em banheiro, cozinha, área de serviço ou área externa', 'Adiciona proteção DR.', 'Circuito em área molhada ou externa precisa de DR.', 'Dispositivo DR', 'S16', 'NBR 5410'),
  ('R09', 'Há circuito novo e o quadro NÃO tem espaço', 'Adiciona serviço no quadro.', 'Não há espaço no quadro para os novos disjuntores.', 'Troca/ampliação do quadro', 'S17', '—'),
  ('R10', 'Há circuito novo e quadro = Não sei', 'Mostra alerta.', 'Confira se há espaço no quadro para os novos disjuntores.', '—', null, '—'),
  ('R11', 'Wi-Fi não chega em todos os cômodos', 'Adiciona repetidor/mesh.', 'Aparelhos Wi-Fi precisam de sinal 2,4 GHz no local.', 'Repetidor ou roteador mesh', 'S18', 'Manual do fabricante'),
  ('R12', 'Total de aparelhos Wi-Fi acima do limite', 'Sugere trocar parte por Zigbee + central.', 'Muitos aparelhos Wi-Fi podem deixar a rede instável.', '—', null, 'Parâmetro: limite = 20 (ajustar com testes)'),
  ('R13', 'Projeto tem aparelho Zigbee', 'Inclui 1 central Zigbee da mesma família.', 'Aparelhos Zigbee precisam de central.', 'Instalação da central', 'S12', 'Manual do fabricante'),
  ('R14', 'Ar e TV no mesmo cômodo', 'Usa 1 controle infravermelho para os dois.', '—', '—', null, 'Economia para o cliente'),
  ('R15', 'Mais de 4 teclas de Luz no mesmo cômodo', 'Divide em mais de um interruptor.', 'Interruptores têm até 4 teclas. Ajuste se ficam em caixas diferentes.', '—', null, '—'),
  ('R16', 'Câmera em área externa', 'Recomenda câmera com detecção de pessoas e IP66/IP67.', 'Coloque a placa "ambiente monitorado" e não filme a área do vizinho (LGPD).', '—', null, 'LGPD'),
  ('R17', 'Interruptor paralelo (three-way)', 'Não é perguntado no MVP.', 'Confira na obra se há paralelo: exige modelo compatível.', '—', null, '—')
insert into public.produtos (id, item, tipo, marca, modelo, nome, app, alexa, google, protocolo, neutro, tensao, corrente_max, potencia_max, teclas, alimentacao, anatel, inmetro, fabricado_brasil, garantia_meses, preco, link, fonte, foto_url, foto_fonte, status, verificado_em, observacoes) values
  ('P001', 'luz', 'INT_TOUCH', 'Intelbras', 'EWS 1001', 'Interruptor Smart Wi-Fi Touch 1 tecla', 'Mibo Smart', 'Verificar', 'Verificar', 'Wi-Fi 2,4 GHz', 'Sim (fabricante)', '100–240 V~ bivolt (fabricante)', '10', '1270 (127 V) / 2200 (220 V)', 1, 'Rede elétrica', 'Verificar', 'Verificar', 'Não', 12, 135.9, 'https://loja.intelbras.com.br/interruptor-smart-touch-ews-1001-branco/p', 'https://backend.intelbras.com/sites/default/files/2026-01/Manual_EWS_1001_01-26_site.pdf', null, null, 'A verificar', null, 'Caixa 4x2. Origem China (importado pela Intelbras). Nº Anatel não publicado no manual: conferir na etiqueta. A Intelbras lançou a linha nova EIW (P025–P028).'),
  ('P002', 'luz', 'INT_TOUCH', 'Intelbras', 'EWS 1002', 'Interruptor Smart Touch 2 teclas', 'Izy Smart / Mibo Smart', 'Verificar', 'Verificar', 'Verificar', 'Verificar', 'Verificar', 'Verificar', 'Verificar', 2, 'Rede elétrica', 'Verificar', 'Verificar', 'Verificar', null, null, null, 'https://loja.intelbras.com.br/interruptor-smart-touch-ews-1002-preto/p', null, null, 'A verificar', null, 'O manual 01/26 ainda cita o app Izy Smart; a Intelbras está migrando para o Mibo Smart. Nº Anatel não publicado.'),
  ('P003', 'luz', 'INT_TOUCH', 'Intelbras', 'EWS 1003', 'Interruptor Smart Touch 3 teclas', 'Izy Smart', 'Verificar', 'Verificar', 'Wi-Fi 2,4 GHz', 'Sim (fabricante)', '100–240 V~ (fabricante)', '10', '1200', 3, 'Rede elétrica', 'Verificar', 'Verificar', 'Verificar', null, null, null, 'https://backend.intelbras.com/sites/default/files/2026-01/Manual_completo_EWS_1003_01-26_site.pdf | https://backend.intelbras.com/sites/default/files/2022-02/Manual_completo_EWS_1003_01-22_site%20%281%29.pdf', null, null, 'A verificar', null, 'Corrente e potência do manual de 2022. Caixa 4x2, fio até 1,5 mm². Neutro deve ser o mesmo das lâmpadas. Cor preta indisponível na loja oficial em 23/11/2026.'),
  ('P004', 'luz', 'INT_TOUCH', 'Intelbras', 'EWS 1004', 'Interruptor Smart Wi-Fi Touch 4 teclas', 'Izy Smart', 'Verificar', 'Verificar', 'Wi-Fi 2,4 GHz', 'Verificar', 'Verificar', 'Verificar', 'Verificar', 4, 'Rede elétrica', 'Verificar', 'Verificar', 'Verificar', null, null, null, 'https://loja.intelbras.com.br/interruptor-smart-wi-fi-touch-4-teclas-ews-1004-branco/p', null, null, 'A verificar', null, null),
  ('P005', 'luz', 'DIMMER', 'Intelbras', 'EWS 251', 'Interruptor Dimmer', 'Izy Smart', 'Sim (fabricante)', 'Sim (fabricante)', 'Verificar', 'Verificar', 'Verificar', 'Verificar', 'Verificar', 1, 'Rede elétrica', 'Verificar', 'Verificar', 'Não', null, null, null, 'https://loja.intelbras.com.br/interruptor-dimmer-ews-251/p', null, null, 'A verificar', null, 'Indisponível na loja oficial em 23/11/2026 (não consta como descontinuado). Só com lâmpadas dimerizáveis e interruptor pulsador. Origem China.'),
  ('P006', 'luz', 'INT_TOUCH', 'Positivo', 'Verificar', 'Smart Interruptor Wi-Fi', 'Positivo Casa Inteligente', 'Verificar', 'Verificar', 'Wi-Fi', 'Verificar', 'Verificar', 'Verificar', 'Verificar', null, 'Rede elétrica', 'Verificar', 'Verificar', 'Verificar', null, null, null, 'https://canaltech.com.br/casa-conectada/positivo-smart-interruptor-wi-fi-lancamento-preco-ficha-tecnica-263281/', null, null, 'A verificar', null, 'Positivo usa plataforma Tuya (fórum Tecnoblog).'),
  ('P007', 'luz', 'LAMPADA', 'Positivo', 'Verificar', 'Smart Lâmpada Wi-Fi', 'Positivo Casa Inteligente', 'Verificar', 'Verificar', 'Wi-Fi', 'Não', 'Verificar', '—', 'Verificar', null, 'Soquete E27', 'Verificar', 'Verificar', 'Verificar', null, null, null, 'https://tecnoblog.net/noticias/positivo-lampada-tomada-camera-sensor-wifi-lancamento-preco-brasil/', null, null, 'A verificar', null, 'Matéria de lançamento antiga; confirmar modelo atual.'),
  ('P008', 'luz', 'INT_TOUCH', 'NovaDigital', 'Verificar', 'Interruptor Inteligente 4x4 Wi-Fi 6 botões Touch', 'Smart Life (anúncio)', 'Sim (anúncio)', 'Sim (anúncio)', 'Wi-Fi', 'Verificar', 'Verificar', 'Verificar', 'Verificar', 6, 'Rede elétrica', 'Verificar', 'Verificar', 'Verificar', null, null, null, 'https://www.magazineluiza.com.br/busca/interruptor+inteligente/', null, null, 'A verificar', null, 'Caixa 4x4.'),
  ('P009', 'luz', 'INT_TOUCH', 'NovaDigital', 'Verificar', 'Interruptor Zigbee 4 teclas Touch', 'Smart Life (anúncio)', 'Sim (anúncio)', 'Sim (anúncio)', 'Zigbee', 'Verificar', 'Verificar', 'Verificar', 'Verificar', 4, 'Rede elétrica', 'Verificar', 'Verificar', 'Verificar', null, null, null, 'https://www.magazineluiza.com.br/busca/interruptor+inteligente/', null, null, 'A verificar', null, 'Zigbee: precisa de central (CENTRAL_ZIGBEE).'),
